beforeExample:
public class Example {
    @Deprecated
    public static void oldMethod() {
        System.out.println("This method is deprecated.");
    }
    public void modernMethod() {
        // ...
    }
}

afterExample:
public class Example {
    @Deprecated(forRemoval = true)
    public static void oldMethod() {
        System.out.println("This method is deprecated.");
    }
    public void modernMethod() {
        // ...
    }
}

negativeExample:
public class NegativeExample {
    // Should not apply if source version is less than 9
    // Or if the annotation already has (forRemoval = true)
    @Deprecated(forRemoval = true)
    public static void alreadyForRemovalMethod() {
        System.out.println("This method is already marked for removal.");
    }
    @SuppressWarnings("unused")
    public void anotherMethod() {}
}
